#include <Arduino.h>

#define CPU_FREQ 160 // 160 should be sufficient, otherwise raise to 240
#define MIN_CYCLE_TIME 5000 //micros

//#define ERASE_BTN 0 // GPIO to erase ESP flash

#define STAT_LED_OFF HIGH
#define STAT_LED_ON LOW

// #define STAT_LED_GN 2 //green onboard LED
// #define STAT_LED_RD 5 //red onboard LED

#define CCT_MODE NORMAL
#define WHITE_LED_RGB_EQUIVALENT {255, 198, 175} // About 4200 Kelvin -24 green

// Dimming curves per channel (generic hardware), generated by libraries/dimming-curves
// DIMCURVE_DEFAULT:   built-in lookupTable of esp-knx-led
// DIMCURVE_LINEAR, DIMCURVE_GAMMA, DIMCURVE_EXPONENTIAL, DIMCURVE_DALI,
// DIMCURVE_LED_LOW_END_BOOST, DIMCURVE_LED_HYBRID, DIMCURVE_LED_S_CURVE
// Fixed product curves (e.g. PRODUCT_YLDL01YL) override these settings
#define DIM_CURVE_CH1 DIMCURVE_DEFAULT
#define DIM_CURVE_CH2 DIMCURVE_DEFAULT
#define DIM_CURVE_CH3 DIMCURVE_DEFAULT
#define DIM_CURVE_CH4 DIMCURVE_DEFAULT
#define DIM_CURVE_CH5 DIMCURVE_DEFAULT

// curve parameters (shared by all channels)
#define DIM_CURVE_GAMMA 2.2f          // GAMMA, LED_LOW_END_BOOST, LED_S_CURVE
#define DIM_CURVE_EXP_K 5.0f          // EXPONENTIAL
#define DIM_CURVE_PWM_MIN 20          // LED_LOW_END_BOOST
#define DIM_CURVE_HYBRID_T 0.2f       // LED_HYBRID
#define DIM_CURVE_HYBRID_GAMMA_LOW 3.0f
#define DIM_CURVE_HYBRID_GAMMA_HIGH 2.2f

#define DEBUGGING true
